def collapse_ints(nums: list[int]) -> str:
    """See SPEC.md."""
    vals = sorted(set(nums))
    if not vals:
        return ""
    parts: list[str] = []
    i = 0
    n = len(vals)
    while i < n:
        j = i
        while j + 1 < n and vals[j + 1] == vals[j] + 1:
            j += 1
        if j - i + 1 >= 4:
            first, last = vals[i], vals[j]
            f = f"({first})" if first < 0 else str(first)
            l = f"({last})" if last < 0 else str(last)
            parts.append(f"{f}-{l}")
        else:
            for k in range(i, j + 1):
                parts.append(str(vals[k]))
        i = j + 1
    return ",".join(parts)

